css:
.wrapper {
  --d: 180px;
  --h-h: calc(0.425 * var(--d));
  --h-b: calc(0.005 * var(--d));

  --m-h: calc(0.567 * var(--d));
  --m-b: calc(0.005 * var(--d));

  --s-d: calc(0.08 * var(--d));

  --a-d: calc(0.485 * var(--d));

  --col-1: #222930; /*hands*/
  --col-2: #d3263d; /*sec hand*/
  --col-3: #c5d0d3; /*frame*/
  --col-4: #ffffff; /*face*/
  --time-speed: 1;

  width: var(--d);
  height: var(--d);
  position: relative;
  border-radius: 50%;
  box-sizing: border-box;
  filter: url(#light);
}

.bg {
  position: absolute;
  inset: -1%;
  border-radius: inherit;
  background-color: var(--col-4);
  background-image: radial-gradient(circle at 45% 30%, #0000, #00000012);
  border: 1px solid #0005;
  filter: url(#noise);
  box-shadow:
    2px 5px 2px 2px #0146,
    3px 8px 2px 4px #0493,
    8px 16px 8px 3px #0493,
    8px 16px 58px 18px #0003;
}

.border {
  position: absolute;
  inset: -3.5%;
  border-radius: inherit;
  background-color: var(--col-3);
  z-index: -1;
}

.border::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  z-index: 1;
  background-image: conic-gradient(from 150deg, #0008, #fff8, #0008);
  box-shadow:
    inset 2px 2px 2px #fff8,
    inset -1px -1px 1px #0001,
    inset -1px -1px 1px #0001,
    inset 0px 0px 6px 1px #0004;
}

.face {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  mask-image: radial-gradient(circle at center, #000 67%, #0000 67.5%);
}

.hour {
  position: absolute;
  left: 50%;
  width: 4%;
  height: 16%;
  background-color: var(--col-1);
  transform-origin: 50% 312%;
  transform: translateX(-50%) rotate(calc(var(--i) * 30deg));
}

.minute {
  position: absolute;
  left: 50%;
  width: 1.666%;
  height: 7%;
  background-color: var(--col-1);
  transform-origin: 50% 710%;
  transform: translateX(-50%) rotate(calc(var(--i) * 6deg));
}

.hands {
  position: relative;
  width: 100%;
  height: 100%;
  filter: drop-shadow(5px 5px 1px #0142) drop-shadow(5px 5px 3px #0494);
}

.hand-h {
  position: absolute;
  border-bottom: var(--h-h) solid var(--col-1);
  border-left: var(--h-b) solid transparent;
  border-right: var(--h-b) solid transparent;
  width: 6.5%;

  top: 19%;
  left: 50%;
  transform: translateX(-50%);
  transform-origin: 0% 73.33%;

  animation: rot calc(43200s / var(--time-speed)) steps(12, end) infinite;
}

.hand-m {
  position: absolute;
  border-bottom: var(--m-h) solid var(--col-1);
  border-left: var(--h-b) solid transparent;
  border-right: var(--h-b) solid transparent;
  width: 6.5%;

  top: 4%;
  left: 50%;
  transform: translateX(-50%);
  transform-origin: 0% 81%;

  animation: rot calc(3600s / var(--time-speed)) steps(60, end) infinite;
}

.hand-s {
  position: absolute;
  left: 50%;
  top: 20%;
  width: 2%;
  height: 45%;
  transform: translateX(-50%);
  background-color: var(--col-2);
  transform-origin: 1% 66.666%;

  animation: swiss-second calc(60s / var(--time-speed)) linear infinite;
}

.hand-s::after {
  content: "";
  position: absolute;
  top: 50;
  left: 50%;
  transform: translate(-50%, -50%);
  width: var(--s-d);
  height: var(--s-d);
  border-radius: 50%;
  background-color: var(--col-2);
}

.axis {
  position: absolute;
  inset: var(--a-d);
  border-radius: 50%;
  background-color: var(--col-2);
  box-shadow:
    0 0 0 1px #0004,
    0 0 0 2px var(--col-2);
}

@keyframes swiss-second {
  0% {
    rotate: 0deg;
  }

  98.3% {
    rotate: 360deg;
  }

  100% {
    rotate: 360deg;
  }
}

@keyframes rot {
  to {
    rotate: 360deg;
  }
}
